// 1. 责任链基础结构
public abstract class Handler {
    protected Handler next;

    public Handler setNext(Handler next) {
        this.next = next;
        return next;
    }

    public void handle(Request request) {
        if (canHandle(request)) {
            doHandle(request);
        } else if (next != null) {
            next.handle(request);
        }
    }

    protected abstract boolean canHandle(Request request);
    protected abstract void doHandle(Request request);
}

// 2. Filter责任链
public interface Filter {
    void doFilter(ServletRequest request, ServletResponse response, FilterChain chain);
}
public class FilterChain {
    private List<Filter> filters = new ArrayList<>();
    private int index = 0;

    public void addFilter(Filter filter) {
        filters.add(filter);
    }

    public void doFilter(ServletRequest request, ServletResponse response) {
        if (index < filters.size()) {
            filters.get(index++).doFilter(request, response, this);
        }
    }
}

// 3. Spring HandlerInterceptor
public interface HandlerInterceptor {
    default boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        return true;
    }
    default void postHandle(HttpServletRequest request, HttpServletResponse response, Object handler, ModelAndView modelAndView) {
    }
    default void afterCompletion(HttpServletRequest request, HttpServletResponse response, Object handler, Exception ex) {
    }
}
// 注册拦截器
@Configuration
public class WebConfig implements WebMvcConfigurer {
    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(new AuthInterceptor())
                .addPathPatterns("/api/**");
        registry.addInterceptor(new LogInterceptor())
                .addPathPatterns("/**");
    }
}

// 4. 审批流示例
public class ApprovalHandler {
    private ApprovalHandler next;
    private BigDecimal maxAmount;

    public void approve(LeaveRequest request) {
        if (request.getDays() <= maxAmount.intValue()) {
            doApprove(request);
        } else if (next != null) {
            next.approve(request);
        }
    }
}
